  it("exp_re(-f(x) + Derivative(f(x)), r, k)", () => {
    const [x, k] = symbols('x k');
    expect(sympyStr(expRe(add(mul(Rational.of(-1n, 1n, { gcd: 1n }), new AppliedUndef('f', [x])), derivative(new AppliedUndef('f', [x]), [[x, 1]])), SymFunction('r', {}), k))).toBe('-r(k) + r(k + 1)');
  });
